query:
UPDATE course_lessons SET content = REPLACE(content, 
  'The Stop pushbutton is wired NC — when you press it (input goes TRUE), the XIO goes FALSE',
  'The Stop pushbutton is wired NC — when NOT pressed, the input is TRUE (closed circuit provides voltage). When pressed, the input goes FALSE (open circuit). Program it with an XIC instruction so the rung is TRUE when the button is NOT pressed, and goes FALSE (stopping the motor) when pressed'
) WHERE id = 60010;

